import {flightMapData,flightMapSvg} from "./flight-map.js";
import {RECIPES,makeMealWeek,shoppingFromMeals,familyWeek,financeSummary,buildAssistantContext} from "./life-intelligence.js";
import {ROUTINES,validateWorkout,suggestTraining,workoutStats} from "./training-intelligence.js";
