function schoolLessonsForDate(date){const day=new Date(date+"T12:00:00").getDay();if(day>4)return [];return sandraSchoolYear.slots.map(row=>({time:row[0],subject:row[day+1]})).filter(x=>x.subject&&x.subject!=="—")}
function schoolTone(subject){const s=String(subject).toLowerCase();if(/spanish|arabic|islamic/.test(s))return "lesson-language";if(/art|pe|discovery/.test(s))return "lesson-activity";if(/snack|lunch|nap/.test(s))return "lesson-break";if(/welcome/.test(s))return "lesson-welcome";return "lesson-homeroom"}
