function initInteractiveMap(data){const el=$("#flightMap");if(!el)return;if(!window.L){el.classList.add("map-fallback");return}if(flightMapInstance){try{flightMapInstance.remove()}catch(e){}flightMapInstance=null}const L=window.L,map=L.map(el,{zoomControl:false,scrollWheelZoom:false,preferCanvas:true,worldCopyJump:true});flightMapInstance=map;L.tileLayer("https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png",{subdomains:"abcd",maxZoom:19,attribution:"© OpenStreetMap © CARTO"}).addTo(map);L.control.zoom({position:"topright"}).addTo(map);const byCode=new Map(data.points.map(p=>[p.code,p]));for(const route of data.paths){const from=byCode.get(route.from),to=byCode.get(route.to);if(!from||!to)continue;L.polyline([[from.lat,from.lon],[to.lat,to.lon]],{color:"#56d7ce",weight:Math.min(5,1.5+route.count*.55),opacity:.72, smoothFactor:1.5}).addTo(map).bindTooltip(route.from+" → "+route.to+" · "+route.count+" sector"+(route.count===1?"":"s"))}const bounds=[];for(const p of data.points){bounds.push([p.lat,p.lon]);L.circleMarker([p.lat,p.lon],{radius:5,weight:2,color:"#06222c",fillColor:"#62e1d2",fillOpacity:.98}).addTo(map).bindPopup("<b>"+esc(p.code)+"</b><br>"+esc(p.country))}if(bounds.length>1)map.fitBounds(bounds,{padding:[34,34],maxZoom:4});else if(bounds.length===1)map.setView(bounds[0],4);else map.setView([24,45],2);requestAnimationFrame(()=>map.invalidateSize())}
